  1→import { expect, type Page, type Locator } from '@playwright/test';
  2→
  3→/**
  4→ * Page object for SearchPalette component interactions.
  5→ *
  6→ * Encapsulates the command palette overlay used for searching files and folders.
  7→ * Provides locator methods for DOM elements and action methods for interactions.
  8→ */
  9→export class SearchPalettePage {
 10→  constructor(private readonly page: Page) {}
 11→
 12→  // ---------------------------------------------------------------------------
 13→  // Locator methods
 14→  // ---------------------------------------------------------------------------
 15→
 16→  /**
 17→   * The full-screen backdrop overlay (also has role="dialog").
 18→   */
 19→  backdrop(): Locator {
 20→    return this.page.locator('.search-backdrop');
 21→  }
 22→
 23→  /**
 24→   * The palette container (centered card with input + results).
 25→   */
 26→  palette(): Locator {
 27→    return this.page.locator('.search-palette');
 28→  }
 29→
 30→  /**
 31→   * The search text input.
 32→   */
 33→  input(): Locator {
 34→    return this.page.locator('.search-input');
 35→  }
 36→
 37→  /**
 38→   * The results container (role="listbox").
 39→   */
 40→  resultsList(): Locator {
 41→    return this.page.locator('.search-results[role="listbox"]');
 42→  }
 43→
 44→  /**
 45→   * All result item elements.
 46→   */
 47→  resultItems(): Locator {
 48→    return this.page.locator('.search-result-item');
 49→  }
 50→
 51→  /**
 52→   * A specific result item by zero-based index.
 53→   */
 54→  resultItem(index: number): Locator {
 55→    return this.resultItems().nth(index);
 56→  }
 57→
 58→  /**
 59→   * The name element within a specific result item.
 60→   */
 61→  resultName(index: number): Locator {
 62→    return this.resultItem(index).locator('.search-result-name');
 63→  }
 64→
 65→  /**
 66→   * The "no results" message element.
 67→   */
 68→  noResults(): Locator {
 69→    return this.page.locator('.search-no-results');
 70→  }
 71→
 72→  /**
 73→   * The "building index..." indicator.
 74→   */
 75→  buildingIndicator(): Locator {
 76→    return this.page.locator('.search-building');
 77→  }
 78→
 79→  /**
 80→   * The footer bar with keyboard hints and result count.
 81→   */
 82→  footer(): Locator {
 83→    return this.page.locator('.search-footer');
 84→  }
 85→
 86→  /**
 87→   * The result count text in the footer (e.g., "// 3 results").
 88→   */
 89→  footerCount(): Locator {
 90→    return this.page.locator('.search-footer-count');
 91→  }
 92→
 93→  /**
 94→   * The search button in the app header.
 95→   */
 96→  headerSearchButton(): Locator {
 97→    return this.page.locator('.header-search-btn');
 98→  }
 99→
100→  // ---------------------------------------------------------------------------
101→  // Action methods
102→  // ---------------------------------------------------------------------------
103→
104→  /**
105→   * Wait for the search palette to become visible.
106→   */
107→  async waitForOpen(options?: { timeout?: number }): Promise<void> {
108→    await this.backdrop().waitFor({ state: 'visible', ...options });
109→  }
110→
111→  /**
112→   * Wait for the search palette to close (hidden or detached).
113→   */
114→  async waitForClosed(options?: { timeout?: number }): Promise<void> {
115→    await this.backdrop().waitFor({ state: 'hidden', ...options });
116→  }
117→
118→  /**
119→   * Type a query into the search input.
120→   */
121→  async typeQuery(text: string): Promise<void> {
122→    await this.input().fill(text);
123→  }
124→
125→  /**
126→   * Clear the search input.
127→   */
128→  async clearQuery(): Promise<void> {
129→    await this.input().fill('');
130→  }
131→
132→  /**
133→   * Get the number of visible result items.
134→   */
135→  async getResultCount(): Promise<number> {
136→    return await this.resultItems().count();
137→  }
138→
139→  /**
140→   * Get an array of result name texts.
141→   */
142→  async getResultNames(): Promise<string[]> {
143→    const items = this.page.locator('.search-result-item .search-result-name');
144→    const count = await items.count();
145→    const names: string[] = [];
146→    for (let i = 0; i < count; i++) {
147→      const text = await items.nth(i).textContent();
148→      if (text) names.push(text);
149→    }
150→    return names;
151→  }
152→
153→  /**
154→   * Click a result item by zero-based index.
155→   */
156→  async clickResult(index: number): Promise<void> {
157→    await this.resultItem(index).click();
158→  }
159→
160→  /**
161→   * Check whether the palette backdrop is currently visible.
162→   */
163→  async isOpen(): Promise<boolean> {
164→    return await this.backdrop().isVisible();
165→  }
166→
167→  /**
168→   * Get the footer count text (e.g., "// 3 results").
169→   */
170→  async getFooterCountText(): Promise<string> {
171→    return (await this.footerCount().textContent()) ?? '';
172→  }
173→
174→  /**
175→   * Wait for search to complete: index built, query executed, and results rendered.
176→   * Uses Playwright's auto-retrying `expect().toPass()` to handle all timing
177→   * variations (index build, debounce, React render) without racy point-in-time checks.
178→   */
179→  async waitForSearchComplete(options?: { timeout?: number }): Promise<void> {
180→    const timeout = options?.timeout ?? 30000;
181→    await expect(async () => {
182→      // Search is complete when either results or the no-results message is visible
183→      const hasResults = (await this.resultItems().count()) > 0;
184→      const hasNoResults = await this.noResults().isVisible();
185→      expect(hasResults || hasNoResults).toBe(true);
186→    }).toPass({ timeout, intervals: [500] });
187→  }
188→
